def maximumJumps(nums, target):
    n = len(nums)
    # dp[i] represents the maximum number of jumps to reach index i
    # Initialize with -1 to indicate unreachable
    dp = [-1] * n
    dp[0] = 0  # Starting position requires 0 jumps

    for i in range(n):
        if dp[i] == -1:
            continue  # Skip if we can't reach index i

        # Try jumping to all indices j > i
        for j in range(i + 1, n):
            # Check if the jump condition is satisfied
            if abs(nums[j] - nums[i]) <= target:
                # Update dp[j] if this path gives more jumps
                if dp[i] + 1 > dp[j]:
                    dp[j] = dp[i] + 1

    return dp[n - 1]
